```python
import os
import hashlib
from pathlib import Path
from typing import Dict, Optional

def list_files_with_sha256(path: str, recursive: bool = True) -> Dict[str, str]:
    """
    List all files in a given path with their SHA256 hashes.

    Args:
        path (str): The directory path to scan
        recursive (bool): Whether to scan subdirectories recursively (default: True)

    Returns:
        Dict[str, str]: Dictionary with file paths as keys and SHA256 hashes as values

    Raises:
        FileNotFoundError: If the specified path doesn't exist
        PermissionError: If there's no permission to access a file or directory
    """

    def calculate_sha256(file_path: str) -> Optional[str]:
        """Calculate SHA256 hash of a file."""
        try:
            sha256_hash = hashlib.sha256()
            with open(file_path, "rb") as f:
                # Read file in chunks to handle large files efficiently
                for chunk in iter(lambda: f.read(4096), b""):
                    sha256_hash.update(chunk)
            return sha256_hash.hexdigest()
        except (PermissionError, OSError) as e:
            print(f"Error reading file {file_path}: {e}")
            return None

    # Validate input path
    path_obj = Path(path)
    if not path_obj.exists():
        raise FileNotFoundError(f"Path '{path}' does not exist")

    if not path_obj.is_dir():
        raise ValueError(f"Path '{path}' is not a directory")

    file_hashes = {}

    try:
        if recursive:
            # Walk through all subdirectories
            for root, dirs, files in os.walk(path):
                for file in files:
                    file_path = os.path.join(root, file)
                    hash_value = calculate_sha256(file_path)
                    if hash_value:
                        file_hashes[file_path] = hash_value
        else:
            # Only scan the immediate directory
            for item in path_obj.iterdir():
                if item.is_file():
                    hash_value = calculate_sha256(str(item))
                    if hash_value:
                        file_hashes[str(item)] = hash_value

    except PermissionError as e:
        print(f"Permission denied accessing directory: {e}")

    return file_hashes

def print_files_with_hashes(path: str, recursive: bool = True):
    """
    Print all files in a given path with their SHA256 hashes in a formatted way.

    Args:
        path (str): The directory path to scan
        recursive (bool): Whether to scan subdirectories recursively (default: True)
    """
    try:
        file_hashes = list_files_with_sha256(path, recursive)

        if not file_hashes:
            print(f"No files found in '{path}'")
            return

        print(f"Files and SHA256 hashes in '{path}':")
        print("-" * 80)

        for file_path, hash_value in sorted(file_hashes.items()):
            print(f"{hash_value}  {file_path}")

    except Exception as e:
        print(f"Error: {e}")

# Example usage
if __name__ == "__main__":
    # Example 1: Get dictionary of files and hashes
    try:
        files_dict = list_files_with_sha256("/path/to/directory")
        for file_path, sha256_hash in files_dict.items():
            print(f"{sha256_hash} - {file_path}")
    except Exception as e:
        print(f"Error: {e}")

    # Example 2: Print formatted output
    print_files_with_hashes("/path/to/directory")

    # Example 3: Non-recursive scan (only immediate directory)
    print_files_with_hashes("/path/to/directory", recursive=False)
```

